// Parse the agent's JSON reply into an `output` object. If the reply is empty or not valid JSON,
// route the invoice to manual review instead of failing the whole run.
const inv = $('Fetch Contract and SOV Details (mock)').item.json;
const raw = String($json.output ?? '').trim();
let a = null;
try {
  const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
  if (start !== -1 && end > start) a = JSON.parse(raw.slice(start, end + 1));
} catch (e) { a = null; }
if (!a) {
  a = { invoice_id: inv.invoice_id, approved: false, approved_amount: 0, retainage_amount: 0, net_payable: 0,
        discrepancies: ['Automated review returned no usable result - manual review required'],
        notes: 'The AI model returned an empty or unreadable response for this invoice.' };
}
if (!Array.isArray(a.discrepancies)) a.discrepancies = [String(a.discrepancies || 'None')];
a.approved = (a.approved === true || a.approved === 'true');
return { json: { output: a } };
